window.AUTH=window.AUTH||{};window.AUTH["86-1128"]={"d":"86-1128","id":"1987/86-1128","n":"Immigration and Naturalization Service v. Abudu","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for the petitioner","date":"","url":"https://www.justice.gov/osg/media/204791/dl?inline","side":"pet","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/immigration-and-naturalization-service-petitioner-v-assibi-abudu","toa":false,"n":82}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep485/usrep485094/usrep485094.pdf","tr":false,"items":[{"t":"case","label":"Supreme Court, in INS v. Rios-Pineda","cite":"471 U.S. 444","y":1985,"id":"1984/83-2032","sc":1,"op":1,"sum":"Section 244(a)(1) of the Immigration and Nationality Act allows the Attorney General to suspend an alien's deportation if the alien has been present in the United States for a continuous period of at least seven years, is of good moral character, and demonstrates that deportation would result in extreme hardship to the alien or to the alien's spouse or child, who is a United States citizen. Even if these …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"INS v. Phinpathya","cite":"464 U.S. 183","id":"1983/82-91","sc":1,"op":2,"sum":"The Court held that the “continuous physical presence” requirement for suspension of deportation in the Immigration and Nationality Act should be interpreted literally.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"INS v. Jong Ha Wang","cite":"450 U.S. 139","y":1981,"id":"1980/80-485","sc":1,"op":7,"sum":"The Board did not exceed its authority and the Court of Appeals erred in ordering that the case be reopened. Respondents' allegations of hardship were in the main conclusory and unsupported by affidavit, as required by the applicable regulations. Moreover, the Court of Appeals improvidently encroached on the authority which the Act confers on the Attorney General and his delegates to define \"extreme hardship\" in the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"FTC v. Pacific States Paper Trade Ass'n","cite":"273 U.S. 52","y":1927,"id":"scdb/1926-184","sc":1,"sum":"1. Where the facts stipulated before the Federal Trade Commission showed that wholesale dealers dominating the. trade, in a certain commodity in Several States were members of local and general trade associations; that uniform prices in intrastate sales were fixed and diligently enforced by the local associations, and in the case of one of them, were, by understanding among its members, to be applied to sales made …","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Cruz-Lopez v. INS","cite":"802 F.2d 1518","url":"https://www.courtlistener.com/c/F.2d/802/1518/","op":4,"by":{"0":""}},{"t":"case","label":"Diaz-Escobar v. INS.","cite":"782 F.2d 1488","y":1986,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/782/1488/","by":{"0":""}},{"t":"case","label":"Ganjour v. INS","cite":"796 F.2d 832","y":1986,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/796/832/","by":{"0":""}},{"t":"case","label":"Yousif v. INS","cite":"794 F.2d 236","y":1986,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/794/236/","by":{"0":""}},{"t":"case","label":"Haftlang v. INS","cite":"790 F.2d 140","y":1986,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/790/140/","by":{"0":""}},{"t":"case","label":"Maroufi v. INS","cite":"772 F.2d 597","y":1985,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/772/597/","op":1,"by":{"0":""}},{"t":"case","label":"Ananeh-Firempong v. INS","cite":"766 F.2d 621","y":1985,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/766/621/","op":1,"by":{"0":""}},{"t":"case","label":"United States v. Sutton","cite":"767 F.2d 726","y":1985,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/767/726/","by":{"0":""}},{"t":"case","label":"United States v. Vergara","cite":"714 F.2d 21","y":1983,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/714/21/","op":1,"by":{"0":""}},{"t":"case","label":"Lazo-Majano v. INS","cite":"813 F.2d 1432","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/813/1432/","by":{"0":""}},{"t":"case","label":"Diaz-Escobar v. INS","cite":"792 F.2d 1488","y":1986,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/792/1488/","by":{"0":""}},{"t":"case","label":"Marroquin-Manriquez v. INS","cite":"699 F.2d 129","url":"https://www.courtlistener.com/c/F.2d/699/129/","sum":"Noting \"the necessary application of expertise implicated in the determination that a fear of persecution is well-founded\".","sumSrc":"brief:0","by":{"0":""}},{"t":"case","label":"Mendez-Efrain v. INS","cite":"813 F.2d 279","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/813/279/","by":{"0":""}},{"t":"case","label":"Kaveh-Haghigy v. INS","cite":"788 F.2d 1321","y":1986,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/788/1321/","sum":"Noting that where alien seeks asylum or withholding of deportation by way of a motion to reopen, \"the government's actions are reviewed under a more lenient abuse of discretion standard\".","sumSrc":"brief:0","by":{"0":""}},{"t":"case","label":"Sang Seup Shin v. INS","cite":"750 F.2d 122","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/750/122/","by":{"0":""}},{"t":"case","label":"Ford Motor Credit Co. v. Milhollin","cite":"444 U.S. 555","y":1980,"id":"1979/78-1487","sc":1,"sum":"TILA does not mandate a general rule of disclosure for acceleration clauses.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Bowles v. Seminole Rock Co.","cite":"325 U.S. 410","y":1945,"id":"scdb/1944-069","sc":1,"by":{"0":""}},{"t":"case","label":"Williams v. INS","cite":"773 F.2d 8","y":1985,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/773/8/","by":{"0":""}},{"t":"case","label":"Le Blanc v. INS","cite":"715 F.2d 685","y":1983,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/715/685/","op":1,"by":{"0":""}},{"t":"case","label":"Balani v. INS","cite":"669 F.2d 1157","y":1982,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/669/1157/","by":{"0":""}},{"t":"case","label":"Achacoso-Sanchez v. INS","cite":"779 F.2d 1260","y":1985,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/779/1260/","by":{"0":""}},{"t":"case","label":"Wong Wing Hang v. INS","cite":"360 F.2d 715","y":1966,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/360/715/","by":{"0":""}},{"t":"case","label":"Dolores v. INS","cite":"772 F.2d 223","y":1985,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/772/223/","by":{"0":""}},{"t":"case","label":"Villena v. INS","cite":"622 F.2d 1352","y":1980,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/622/1352/","op":1,"by":{"0":""}},{"t":"case","label":"Ghadessi v. INS","cite":"797 F.2d 804","y":1986,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/797/804/","by":{"0":""}},{"t":"case","label":"Bahramnia v. INS","cite":"782 F.2d 1243","url":"https://www.courtlistener.com/c/F.2d/782/1243/","op":1,"by":{"0":""}},{"t":"case","label":"Sanchez v. INS","cite":"707 F.2d 1523","url":"https://www.courtlistener.com/c/F.2d/707/1523/","by":{"0":""}},{"t":"case","label":"Minwalla v. INS","cite":"706 F.2d 831","y":1983,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/706/831/","by":{"0":""}},{"t":"case","label":"Kashani v. INS","cite":"547 F.2d 376","y":1977,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/547/376/","by":{"0":""}},{"t":"case","label":"Saballo-Cortez v. INS","cite":"761 F.2d 1259","y":1985,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/761/1259/","by":{"0":""}},{"t":"case","label":"Bowman Transp., Inc. v. Arkansas-Best Freight System, Inc.","cite":"419 U.S. 281","y":1974,"id":"1974/73-1055","sc":1,"op":1,"sum":"The Supreme Court held that the ICC based its decisions on consideration of relevant factors. While the ICC could have explained its reasoning more clearly, the Court did not feel the decisions were arbitrary and capricious. The Court also remanded the case to determine whether Bowman should receive the excess authority the ICC granted.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Cities of Campbell v. FERC","cite":"770 F.2d 1180","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/770/1180/","op":1,"by":{"0":""}},{"t":"case","label":"ICC v. Jersey City","cite":"322 U.S. 503","y":1944,"id":"scdb/1943-065","sc":1,"sum":"An order of the Interstate Commerce Commission authorized a fare increase from 8 cents to 9 cents. Upon finding that collection of the 9-cent fare was impracticable, the Commission modified its order so as to authorize a fare of 11 tokens for $1.00 or a cash fare of 10 cents. The Commission later reopened the proceeding, but only to consider the propriety and lawfulness of the modification of its original order. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Vermont Yankee Nuclear Power Corp. v. NRDC","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"sum":"In No. 76-419, after extensive hearings before the Atomic Safety and Licensing Board (Licensing Board) and over respondents' objections, the Atomic Energy Commission (AEC) granted petitioner Vermont Yankee Nuclear Power Corp. a license to operate a nuclear power plant, and this ruling was affirmed by the Atomic Safety and Licensing Appeal Board (Appeal Board). Subsequently, the AEC, specifically referring to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. ICC","cite":"396 U.S. 491","y":1970,"id":"1969/28","sc":1,"sum":"The Supreme Court held that substantial evidence supported the ICC’s decision. The savings, service improvements, and conditions agreed to by the merging railroads far outweighed the loss of competition. The court also upheld the ICC’s decision on the ratio for the exchange of stock that would take place during the merger. Justice William O. Douglas did not participate.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Nance v. EPA","cite":"645 F.2d 701","url":"https://www.courtlistener.com/c/F.2d/645/701/","op":1,"by":{"0":""}},{"t":"case","label":"United States v. Pierce Auto Freight Lines, Inc.","cite":"327 U.S. 515","y":1946,"id":"scdb/1945-097","sc":1,"sum":"that 'an order of the Commission granting both applications was valid. Pp. 517, 523.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Mobil Oil Corp. v. ICC","cite":"685 F.2d 624","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/685/624/","by":{"0":""}},{"t":"case","label":"Duval Corp. v. Donovan","cite":"650 F.2d 1051","y":1981,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/650/1051/","op":1,"by":{"0":""}},{"t":"case","label":"United States v. Davis","cite":"604 F.2d 474","y":1979,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/604/474/","by":{"0":""}},{"t":"case","label":"United States v. Agurs","cite":"427 U.S. 97","id":"1975/75-491","sc":1,"sum":"The prosecutor's failure to tender Sewell's criminal record to the defense did not deprive respondent of a fair trial as guaranteed by the Due Process Clause of the Fifth Amendment, where it appears that the record was not requested by defense counsel and gave rise to no inference -of perjury, that the trial judge remained convinced of respondent's guilt beyond a reasonable doubt after considering the criminal …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Massa","cite":"804 F.2d 1020","y":1986,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/804/1020/","by":{"0":""}},{"t":"case","label":"Consolo v. FMC","cite":"383 U.S. 607","id":"1965/63","sc":1,"by":{"0":""}},{"t":"case","label":"United States v. Carlo Bianchi & Co.","cite":"373 U.S. 709","y":1963,"id":"1962/529","sc":1,"sum":"In a suit on a government contract, apart from questions of fraud, determination of the finality to be attached to a departmental decision on a question arising under a \"disputes\" clause must rest solely on consideration of the record before the department, and no new evidence may be received or considered. Pp. 709-718. 157 Ct. Cl. -, judgment vacated and cause remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Woodby v. INS","cite":"385 U.S. 276","y":1966,"id":"1966/40","sc":1,"sum":"No deportation order may be entered unless the Government proves by clear, unequivocal, and convincing evidence that the facts alleged as grounds for deportation are true.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Adolph Coors Co. v. FTC","cite":"497 F.2d 1178","y":1974,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/497/1178/","by":{"0":""}},{"t":"case","label":"Local One, Amalgamated Lithographers v. NLRB","cite":"729 F.2d 172","y":1984,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/729/172/","by":{"0":""}},{"t":"case","label":"Hedstrom Co. v. NLRB","cite":"629 F.2d 305","y":1980,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/629/305/","by":{"0":""}},{"t":"case","label":"National Macaroni Mfrs. Ass'n v. FTC","cite":"345 F.2d 421","y":1965,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/345/421/","by":{"0":""}},{"t":"case","label":"United States v. Diebold, Inc.","cite":"369 U.S. 654","y":1962,"id":"1961/286","sc":1,"op":1,"sum":"In this civi! antitrust action by the Government challenging respondent's acquisition of the assets of another corporation as being violative of § 7 of the Clayton Act, the affidavits, exhibits and depositions before the District Court raised a genuine issue as to ultimate facts material to the question whether the acquired corporation was a \"failing company\" under the doctrine of InternationalShoe Co. v. Federal …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Conti v. INS","cite":"780 F.2d 698","y":1985,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/780/698/","op":1,"by":{"0":""}},{"t":"case","label":"Tupacyupanqui-Marin v. INS","cite":"447 F.2d 603","y":1971,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/447/603/","by":{"0":""}},{"t":"case","label":"Luciano-Vincente v. INS","cite":"786 F.2d 706","y":1986,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/786/706/","by":{"0":""}},{"t":"case","label":"Osuchukwu v. INS","cite":"744 F.2d 1136","y":1984,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/744/1136/","sum":"Noting, in the context of direct review of denial of suspension of deportation, that the BIA is required simply to \"'consider the issues raised, and announce its decision in terms sufficient to enable a reviewing court to perceive that it has heard and thought and not merely reacted'\".","sumSrc":"brief:0","by":{"0":""}},{"t":"case","label":"Shoaee v. INS","cite":"704 F.2d 1079","url":"https://www.courtlistener.com/c/F.2d/704/1079/","by":{"0":""}},{"t":"case","label":"INS v. Stevic","cite":"467 U.S. 407","y":1984,"id":"1983/82-973","sc":1,"op":13,"sum":"An alien must establish a clear probability of persecution to avoid deportation under § 243(h).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Duran v. INS","cite":"756 F.2d 1338","url":"https://www.courtlistener.com/c/F.2d/756/1338/","op":1,"by":{"0":""}},{"t":"case","label":"Chavez v. INS","cite":"723 F.2d 1431","y":1984,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/723/1431/","sum":"Rejecting argument that under Section 208.11, a motion to reopen to apply for asylum should be granted upon a lesser showing than that required for other types of motions to reopen.","sumSrc":"brief:0","by":{"0":""}},{"t":"case","label":"INS v. Miranda","cite":"459 U.S. 14","y":1982,"id":"1982/82-29","sc":1,"sum":"Regardless of whether or not even \"affirmative misconduct\" will estop the Government from enforcing the immigration laws, the evidence here did not rise to that level. Respondent showed only that the Government failed to process his application promptly. Even if the INS arguably was negligent in not acting more expeditiously, neither such conduct nor the harm to respondent was sufficient to estop the Government. Cf. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Fiallo v. Bell","cite":"430 U.S. 787","y":1977,"id":"1976/75-6297","sc":1,"sum":"Sections 101 (b) (1) (D) and 101 (b) (2) of the Immigration and Nationality Act of 1952, which have the effect of excluding the relationship between an illegitimate child and his natural father (as opposed to his natural mother) from the special preference immigration status accorded by the Act to the \"child\" or \"parent\" of a United States citizen or lawful permanent resident, held not to be unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Hampton v. Mow Sun Wong","cite":"426 U.S. 88","id":"1974/73-1596","sc":1,"op":1,"sum":"The Civil Service Commission (CSC) regulation barring noncitizens, including lawfully admitted resident aliens, from employment in the federal competitive civil service held unconstitutional as depriving such resident aliens of liberty without due process of law in violation of the Fifth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Mathews v. Diaz","cite":"426 U.S. 67","y":1976,"id":"1974/73-1046","sc":1,"sum":"Title 42 U. S. C. § 1395o (2) qualifies for enrollment in the Medicare supplemental medical insurance program residents of the United States who are 65 or older, but in subsection (B) denies eligibility to aliens unless they have been admitted for permanent residence and also have resided in the United States for at least five years. Appellee Diaz filed a class action suit in the District Court attacking the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Kleindienst v. Mandel","cite":"408 U.S. 753","y":1972,"id":"1971/71-16","sc":1,"sum":"The Court held that the First Amendment did not obligate Kleindienst to grant a waiver to Mandel.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"INS v. Lopez-Mendoza","cite":"468 U.S. 1032","y":1984,"id":"1983/83-491","sc":1,"sum":"In both criminal and civil proceedings, the \"body\" or identity of a defendant is never suppressible as fruit of an illegal arrest. This alone was sufficient basis to uphold Lopez-Mendoza's deportation order. Moreover, deportation proceedings are civil actions and the protections afforded defendants in the criminal context do not apply.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Jay v. Boyd","cite":"351 U.S. 345","y":1956,"id":"1955/503","sc":1,"sum":"The Attorney General has properly exercised his discretionary powers under the statute in this case, and denial of the application is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Platero-Reymundo v. INS","cite":"807 F.2d 865","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/807/865/","by":{"0":""}},{"t":"case","label":"Saldana v. INS","cite":"762 F.2d 824","y":1985,"url":"https://www.courtlistener.com/c/F.2d/762/824/","by":{"0":""}},{"t":"case","label":"Larimi v. INS","cite":"782 F.2d 1494","y":1986,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/782/1494/","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":""}},{"t":"usc","label":"8 U.S.C. § 1158","url":"https://www.law.cornell.edu/uscode/text/8/1158","subs":["(a)"],"stext":{"head":"§1158. Asylum","paras":[[0,"(a) Authority to apply for asylum"],[0,"(1) In general"],[1,"Any alien who is physically present in the United States or who arrives in the United States (whether or not at a designated port of arrival and including an alien who is brought to the United States after having been interdicted in international or United States waters), irrespective of such alien's status, may apply for asylum in accordance with this section or, where applicable, section 1225(b) of this title."],[0,"(2) Exceptions"],[0,"(A) Safe third country"],[2,"Paragraph (1) shall not apply to an alien if the Attorney General determines that the alien may be removed, pursuant to a bilateral or multilateral agreement, to a country (other than the country of the alien's nationality or, in the case of an alien having no nationality, the country of the alien's last habitual residence) in which the alien's life or freedom would not be threatened on account of race, religion, nationality, membership in a particular social group, or political opinion, and where the alien would have access to a full and fair procedure for determining a claim to asylum or equivalent temporary protection, unless the Attorney General finds that it is in the public interest for the alien to receive asylum in the United States."],[0,"(B) Time limit"],[2,"Subject to subparagraph (D), paragraph (1) shall not apply to an alien unless the alien demonstrates by clear and convincing evidence that the application has been filed within 1 year after the date of the alien's arrival in the United States."],[0,"(C) Previous asylum applications"],[2,"Subject to subparagraph (D), paragraph (1) shall not apply to an alien if the alien has previously applied for asylum and had such application denied."],[0,"(D) Changed circumstances"],[2,"An application for asylum of an alien may be considered, notwithstanding subparagraphs (B) and (C), if the alien demonstrates to the satisfaction of the Attorney General either the existence of changed circumstances which materially affect the applicant's eligibility for asylum or extraordinary circumstances relating to the delay in filing an application within the period specified in subparagraph (B)."],[0,"(E) Applicability"],[2,"Subparagraphs (A) and (B) shall not apply to an unaccompanied alien child (as defined in section 279(g) of title 6)."],[0,"(3) Limitation on judicial review"],[1,"No court shall have jurisdiction to review any determination of the Attorney General under paragraph (2)."],[0,"(b) Conditions for granting asylum"],[0,"(1) In general"],[0,"(A) Eligibility"],[2,"The Secretary of Homeland Security or the Attorney General may grant asylum to an alien who has applied for asylum in accordance with the requirements and procedures established by the Secretary of Homeland Security or the Attorney General under this section if the Secretary of Homeland Security or the Attorney General determines that such alien is a refugee within the meaning of section 1101(a)(42)(A) of this title."],[0,"(B) Burden of proof"],[0,"(i) In general"],[3,"The burden of proof is on the applicant to establish that the applicant is a refugee, within the meaning of section 1101(a)(42)(A) of this title. To establish that the applicant is a refugee within the meaning of such section, the applicant must establish that race, religion, nationality, membership in a particular social group, or political opinion was or will be at least one central reason for persecuting the applicant."],[0,"(ii) Sustaining burden"],[3,"The testimony of the applicant may be sufficient to sustain the applicant's burden without corroboration, but only if the applicant satisfies the trier of fact that the applicant's testimony is credible, is persuasive, and refers to specific facts sufficient to demonstrate that the applicant is a refugee. In determining whether the applicant has met the applicant's burden, the trier of fact may weigh the credible testimony along with other evidence of record. Where the trier of fact determines that the applicant should provide evidence that corroborates otherwise credible testimony, such evidence must be provided unless the applicant does not have the evidence and cannot reasonably obtain the evidence."],[0,"(iii) Credibility determination"],[3,"Considering the totality of the circumstances, and all relevant factors, a trier of fact may base a credibility determination on the demeanor, candor, or responsiveness of the applicant or witness, the inherent plausibility of the applicant's or witness's account, the consistency between the applicant's or witness's written and oral statements (whenever made and whether or not under oath, and considering the circumstances under which the statements were made), the internal consistency of each such statement, the consistency of such statements with other evidence of record (including the reports of the Department of State on country conditions), and any inaccuracies or falsehoods in such statements, without regard to whether an inconsistency, inaccuracy, or falsehood goes to the heart of the applicant's claim, or any other relevant factor. There is no presumption of credibility, however, if no adverse credibility determination is explicitly made, the applicant or witness shall have a rebuttable presumption of credibility on appeal."],[0,"(2) Exceptions"],[0,"(A) In general"],[2,"Paragraph (1) shall not apply to an alien if the Attorney General determines that—"],[3,"(i) the alien ordered, incited, assisted, or otherwise participated in the persecution of any person on account of race, religion, nationality, membership in a particular social group, or political opinion;"],[3,"(ii) the alien, having been convicted by a final judgment of a particularly serious crime, constitutes a danger to the community of the United States;"],[3,"(iii) there are serious reasons for believing that the alien has committed a serious nonpolitical crime outside the United States prior to the arrival of the alien in the United States;"],[3,"(iv) there are reasonable grounds for regarding the alien as a danger to the security of the United States;"],[3,"(v) the alien is described in subclause (I), (II), (III), (IV), or (VI) of section 1182(a)(3)(B)(i) of this title or section 1227(a)(4)(B) of this title (relating to terrorist activity), unless, in the case only of an alien described in subclause (IV) of section 1182(a)(3)(B)(i) of this title, the Attorney General determines, in the Attorney General's discretion, that there are not reasonable grounds for regarding the alien as a danger to the security of the United States; or"],[3,"(vi) the alien was firmly resettled in another country prior to arriving in the United States."],[0,"(B) Special rules"],[0,"(i) Conviction of aggravated felony"],[3,"For purposes of clause (ii) of subparagraph (A), an alien who has been convicted of an aggravated felony shall be considered to have been convicted of a particularly serious crime."],[0,"(ii) Offenses"],[3,"The Attorney General may designate by regulation offenses that will be considered to be a crime described in clause (ii) or (iii) of subparagraph (A)."],[0,"(C) Additional limitations"],[2,"The Attorney General may by regulation establish additional limitations and conditions, consistent with this section, under which an alien shall be ineligible for asylum under paragraph (1)."],[0,"(D) No judicial review"],[2,"There shall be no judicial review of a determination of the Attorney General under subparagraph (A)(v)."],[0,"(3) Treatment of spouse and children"],[0,"(A) In general"],[2,"A spouse or child (as defined in section 1101(b)(1)(A), (B), (C), (D), or (E) of this title) of an alien who is granted asylum under this subsection may, if not otherwise eligible for asylum under this section, be granted the same status as the alien if accompanying, or following to join, such alien."],[0,"(B) Continued classification of certain aliens as children"],[2,"An unmarried alien who seeks to accompany, or follow to join, a parent granted asylum under this subsection, and who was under 21 years of age on the date on which such parent applied for asylum under this section, shall continue to be classified as a child for purposes of this paragraph and section 1159(b)(3) of this title, if the alien attained 21 years of age after such application was filed but while it was pending."],[0,"(C) Initial jurisdiction"],[2,"An asylum officer (as defined in section 1225(b)(1)(E) of this title) shall have initial jurisdiction over any asylum application filed by an unaccompanied alien child (as defined in section 279(g) of title 6), regardless of whether filed in accordance with this section or section 1225(b) of this title."],[0,"(c) Asylum status"],[0,"(1) In general"],[1,"In the case of an alien granted asylum under subsection (b), the Attorney General—"],[2,"(A) shall not remove or return the alien to the alien's country of nationality or, in the case of a person having no nationality, the country of the alien's last habitual residence;"],[2,"(B) shall authorize the alien to engage in employment in the United States and provide the alien with appropriate endorsement of that authorization; and"],[2,"(C) may allow the alien to travel abroad with the prior consent of the Attorney General."],[0,"(2) Termination of asylum"],[1,"Asylum granted under subsection (b) does not convey a right to remain permanently in the United States, and may be terminated if the Attorney General determines that—"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1158?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1158. Asylum","tname":"Aliens and Nationality","by":{"0":""}},{"t":"usc","label":"8 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/8/1253","subs":["(h)"],"by":{"0":""}},{"t":"usc","label":"8 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/8/1251","subs":["(a)(11)"],"by":{"0":""}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(23)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1182. Inadmissible aliens","tname":"Aliens and Nationality","by":{"0":""}},{"t":"usc","label":"8 U.S.C. § 1255","url":"https://www.law.cornell.edu/uscode/text/8/1255","subs":["(a)(2)"],"stext":{"head":"§1255. Adjustment of status of nonimmigrant to that of person admitted for permanent residence","paras":[[0,"(a) Status as person admitted for permanent residence on application and eligibility for immigrant visa"],[0,"The status of an alien who was inspected and admitted or paroled into the United States or the status of any other alien having an approved petition for classification as a VAWA self-petitioner may be adjusted by the Attorney General, in his discretion and under such regulations as he may prescribe, to that of an alien lawfully admitted for permanent residence if (1) the alien makes an application for such adjustment, (2) the alien is eligible to receive an immigrant visa and is admissible to the United States for permanent residence, and (3) an immigrant visa is immediately available to him at the time his application is filed."],[0,"(b) Record of lawful admission for permanent residence; reduction of preference visas"],[0,"Upon the approval of an application for adjustment made under subsection (a), the Attorney General shall record the alien's lawful admission for permanent residence as of the date the order of the Attorney General approving the application for the adjustment of status is made, and the Secretary of State shall reduce by one the number of the preference visas authorized to be issued under sections 1152 and 1153 of this title within the class to which the alien is chargeable for the fiscal year then current."],[0,"(c) Alien crewmen, aliens continuing or accepting unauthorized employment, and aliens admitted in transit without visa"],[0,"Other than an alien having an approved petition for classification as a VAWA self-petitioner, subsection (a) shall not be applicable to (1) an alien crewman; (2) subject to subsection (k), an alien (other than an immediate relative as defined in section 1151(b) of this title or a special immigrant described in section 1101(a)(27)(H), (I), (J), or (K) of this title) who hereafter continues in or accepts unauthorized employment prior to filing an application for adjustment of status or who is in unlawful immigration status on the date of filing the application for adjustment of status or who has failed (other than through no fault of his own or for technical reasons) to maintain continuously a lawful status since entry into the United States; (3) any alien admitted in transit without visa under section 1182(d)(4)(C) of this title; (4) an alien (other than an immediate relative as defined in section 1151(b) of this title) who was admitted as a nonimmigrant visitor without a visa under section 1182(l) of this title or section 1187 of this title; (5) an alien who was admitted as a nonimmigrant described in section 1101(a)(15)(S) of this title,1 (6) an alien who is deportable under section 1227(a)(4)(B) of this title; (7) any alien who seeks adjustment of status to that of an immigrant under section 1153(b) of this title and is not in a lawful nonimmigrant status; or (8) any alien who was employed while the alien was an unauthorized alien, as defined in section 1324a(h)(3) of this title, or who has otherwise violated the terms of a nonimmigrant visa."],[0,"(d) Alien admitted for permanent residence on conditional basis; fiancee or fiance of citizen"],[0,"The Attorney General may not adjust, under subsection (a), the status of an alien lawfully admitted to the United States for permanent residence on a conditional basis under section 1186a of this title. The Attorney General may not adjust, under subsection (a), the status of a nonimmigrant alien described in section 1101(a)(15)(K) of this title except to that of an alien lawfully admitted to the United States on a conditional basis under section 1186a of this title as a result of the marriage of the nonimmigrant (or, in the case of a minor child, the parent) to the citizen who filed the petition to accord that alien's nonimmigrant status under section 1101(a)(15)(K) of this title."],[0,"(e) Restriction on adjustment of status based on marriages entered while in admissibility or deportation proceedings; bona fide marriage exception"],[0,"(1) Except as provided in paragraph (3), an alien who is seeking to receive an immigrant visa on the basis of a marriage which was entered into during the period described in paragraph (2) may not have the alien's status adjusted under subsection (a)."],[0,"(2) The period described in this paragraph is the period during which administrative or judicial proceedings are pending regarding the alien's right to be admitted or remain in the United States."],[0,"(3) Paragraph (1) and section 1154(g) of this title shall not apply with respect to a marriage if the alien establishes by clear and convincing evidence to the satisfaction of the Attorney General that the marriage was entered into in good faith and in accordance with the laws of the place where the marriage took place and the marriage was not entered into for the purpose of procuring the alien's admission as an immigrant and no fee or other consideration was given (other than a fee or other consideration to an attorney for assistance in preparation of a lawful petition) for the filing of a petition under section 1154(a) of this title or subsection (d) or (p) 2 of section 1184 of this title with respect to the alien spouse or alien son or daughter. In accordance with regulations, there shall be only one level of administrative appellate review for each alien under the previous sentence."],[0,"(f) Limitation on adjustment of status"],[0,"The Attorney General may not adjust, under subsection (a), the status of an alien lawfully admitted to the United States for permanent residence on a conditional basis under section 1186b of this title."],[0,"(g) Special immigrants"],[0,"In applying this section to a special immigrant described in section 1101(a)(27)(K) of this title, such an immigrant shall be deemed, for purposes of subsection (a), to have been paroled into the United States."],[0,"(h) Application with respect to special immigrants"],[0,"In applying this section to a special immigrant described in section 1101(a)(27)(J) of this title—"],[1,"(1) such an immigrant shall be deemed, for purposes of subsection (a), to have been paroled into the United States; and"],[1,"(2) in determining the alien's admissibility as an immigrant—"],[2,"(A) paragraphs (4), (5)(A), (6)(A), (6)(C), (6)(D), (7)(A), and (9)(B) of section 1182(a) of this title shall not apply; and"],[2,"(B) the Attorney General may waive other paragraphs of section 1182(a) of this title (other than paragraphs (2)(A), (2)(B), (2)(C) (except for so much of such paragraph as related to a single offense of simple possession of 30 grams or less of marijuana), (3)(A), (3)(B), (3)(C), and (3)(E)) in the case of individual aliens for humanitarian purposes, family unity, or when it is otherwise in the public interest."],[0,"The relationship between an alien and the alien's natural parents or prior adoptive parents shall not be considered a factor in making a waiver under paragraph (2)(B). Nothing in this subsection or section 1101(a)(27)(J) of this title shall be construed as authorizing an alien to apply for admission or be admitted to the United States in order to obtain special immigrant status described in such section."],[0,"(i) Adjustment in status of certain aliens physically present in United States"],[0,"(1) Notwithstanding the provisions of subsections (a) and (c) of this section, an alien physically present in the United States—"],[1,"(A) who—"],[2,"(i) entered the United States without inspection; or"],[2,"(ii) is within one of the classes enumerated in subsection (c) of this section;"],[1,"(B) who is the beneficiary (including a spouse or child of the principal alien, if eligible to receive a visa under section 1153(d) of this title) of—"],[2,"(i) a petition for classification under section 1154 of this title that was filed with the Attorney General on or before April 30, 2001; or"],[2,"(ii) an application for a labor certification under section 1182(a)(5)(A) of this title that was filed pursuant to the regulations of the Secretary of Labor on or before such date; and"],[1,"(C) who, in the case of a beneficiary of a petition for classification, or an application for labor certification, described in subparagraph (B) that was filed after January 14, 1998, is physically present in the United States on December 21, 2000;"],[0,"may apply to the Attorney General for the adjustment of his or her status to that of an alien lawfully admitted for permanent residence. The Attorney General may accept such application only if the alien remits with such application a sum equalling $1,000 as of the date of receipt of the application, but such sum shall not be required from a child under the age of seventeen, or an alien who is the spouse or unmarried child of an individual who obtained temporary or permanent resident status under section 1160 or 1255a of this title or section 202 of the Immigration Reform and Control Act of 1986 at any date, who—"],[1,"(i) as of May 5, 1988, was the unmarried child or spouse of the individual who obtained temporary or permanent resident status under section 1160 or 1255a of this title or section 202 of the Immigration Reform and Control Act of 1986;"],[1,"(ii) entered the United States before May 5, 1988, resided in the United States on May 5, 1988, and is not a lawful permanent resident; and"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1255?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1255. Adjustment of status of nonimmigrant to that of person admitted for permanent residence","tname":"Aliens and Nationality","by":{"0":""}},{"t":"usc","label":"8 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/8/1254","subs":["(a)(1)"],"op":1,"tname":"Aliens and Nationality","by":{"0":""}},{"t":"usc","label":"8 U.S.C. § 1255A","url":"https://www.law.cornell.edu/uscode/text/8/1255A","subs":["(a)(4)(B)"],"by":{"0":""}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(42)(A)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":""}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)"],"by":{"0":""}}]};